import { QueryClient } from '@tanstack/react-query';

import { ContentLayout } from '@/components/layouts';
import { getTeamsQueryOptions } from '@/features/teams/api/get-teams';
import { CreateTeam } from '@/features/teams/components/create-team';
import { TeamsList } from '@/features/teams/components/teams-list';
import { Authorization, ROLES } from '@/lib/authorization';

export const clientLoader = (queryClient: QueryClient) => async () => {
  const query = getTeamsQueryOptions();

  return (
    queryClient.getQueryData(query.queryKey) ??
    (await queryClient.fetchQuery(query))
  );
};

const TeamsRoute = () => {
  return (
    <ContentLayout title="Teams">
      <Authorization
        forbiddenFallback={<div>Only admin can view this.</div>}
        allowedRoles={[ROLES.ADMIN]}
      >
        <div className="flex justify-end">
          <CreateTeam />
        </div>
        <div className="mt-4">
          <TeamsList />
        </div>
      </Authorization>
    </ContentLayout>
  );
};

export default TeamsRoute;
EOF
